-- Compliance (docs/plan.md §1.35; HIPAA §164.312(b), SOC 2 CC7.2, PCI DSS 10): `audit_event`
-- records who read or changed what, when and from where, one row per request to a session route,
-- per sign-in and refused sign-in. And `tenant.retired_at`, for offboarding a client. A new table
-- and a nullable column only, so the previous Worker keeps working: it never reads either.
-- Generated by drizzle-kit; the grants, row-level security and trigger at the end are hand-written.
CREATE TABLE "audit_event" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid,
	"actor_kind" text NOT NULL,
	"actor_user_id" uuid,
	"actor_email" text,
	"actor_role" text,
	"action" text NOT NULL,
	"outcome" text NOT NULL,
	"http_status" integer,
	"target" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"ip" text,
	"user_agent" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "audit_event_outcome_check" CHECK ("audit_event"."outcome" in ('ok', 'refused', 'error')),
	CONSTRAINT "audit_event_actor_kind_check" CHECK ("audit_event"."actor_kind" in ('user', 'system', 'anonymous'))
);
--> statement-breakpoint
ALTER TABLE "tenant" ADD COLUMN "retired_at" timestamp with time zone;--> statement-breakpoint
CREATE INDEX "audit_event_tenant_idx" ON "audit_event" USING btree ("tenant_id","created_at");--> statement-breakpoint
CREATE INDEX "audit_event_actor_idx" ON "audit_event" USING btree ("actor_user_id","created_at");--> statement-breakpoint
CREATE INDEX "audit_event_created_idx" ON "audit_event" USING btree ("created_at");

--> statement-breakpoint

-- Append-only: no UPDATE or DELETE grant to the runtime, and a trigger refuses both for everyone.
-- Rows past their retention are removed only by the owner, disabling the trigger to do so.
GRANT SELECT, INSERT ON audit_event TO cs_runtime;
--> statement-breakpoint
ALTER TABLE audit_event ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
ALTER TABLE audit_event FORCE ROW LEVEL SECURITY;
--> statement-breakpoint
-- Read: a client's rows in that client's scope; rows without a client (sign-ins, cross-client
-- back-office lists) only in operator sessions.
CREATE POLICY audit_read ON audit_event FOR SELECT TO PUBLIC
  USING (tenant_id = any(app_tenant_ids()) OR (tenant_id IS NULL AND app_is_operator()));
--> statement-breakpoint
-- Write: into the scope's own clients, or with no client from any scope (a refused sign-in has
-- none yet).
CREATE POLICY audit_write ON audit_event FOR INSERT TO PUBLIC
  WITH CHECK (tenant_id IS NULL OR tenant_id = any(app_tenant_ids()));
--> statement-breakpoint
CREATE TRIGGER audit_event_append_only BEFORE UPDATE OR DELETE ON audit_event
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except();
